import {Beacon} from "../src/Beacon.sol";
import {LibProdDeployV4} from "../src/LibProdDeployV4.sol";

contract SrcOnly {
    function run() external returns (Beacon, bytes memory, string memory, address) {
        Beacon beacon = new Beacon();
